package com.reviewflow.service;
import com.reviewflow.domain.*;import com.reviewflow.repo.*;import org.springframework.stereotype.Service;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import java.util.stream.*;
@Service public class AnalyticsService {private final ReviewSnapshotRepository snapshots;private final QrCodeRepository codes;private final QrScanRepository scans;public AnalyticsService(ReviewSnapshotRepository s,QrCodeRepository c,QrScanRepository q){snapshots=s;codes=c;scans=q;} public record Point(String date,Number value){} public record Overview(Double rating,Integer totalReviews,Integer newReviews,Double ratingChange,long qrScans,Double reviewGrowthPercentage,long averageScansPerDay){}
 public Overview overview(Business b,LocalDate start,LocalDate end){long count=scans(b,start,end);long average=count/Math.max(1,ChronoUnit.DAYS.between(start,end)+1);try{ReviewSnapshot first=at(b.id,start),last=at(b.id,end);LocalDate prevStart=start.minusDays(ChronoUnit.DAYS.between(start,end)+1),prevEnd=start.minusDays(1);Optional<ReviewSnapshot> before=snapshots.findFirstByBusinessIdAndSnapshotDateLessThanEqualOrderBySnapshotDateDesc(b.id,prevStart);Optional<ReviewSnapshot> prevLast=snapshots.findFirstByBusinessIdAndSnapshotDateLessThanEqualOrderBySnapshotDateDesc(b.id,prevEnd);int gained=last.totalReviews-first.totalReviews;Double percent=before.isPresent()&&prevLast.isPresent()&&prevLast.get().totalReviews-before.get().totalReviews!=0?round((gained-(prevLast.get().totalReviews-before.get().totalReviews))*100.0/(prevLast.get().totalReviews-before.get().totalReviews)):null;return new Overview(last.rating,last.totalReviews,gained,round(last.rating-first.rating),count,percent,average);}catch(Exception ignored){return new Overview(null,null,null,null,count,null,average);}}
 public List<Point> reviewPoints(Business b,LocalDate s,LocalDate e){return snapshots.findByBusinessIdAndSnapshotDateBetweenOrderBySnapshotDate(b.id,s,e).stream().map(x->new Point(x.snapshotDate.toString(),x.totalReviews)).toList();} public List<Point> ratingPoints(Business b,LocalDate s,LocalDate e){return snapshots.findByBusinessIdAndSnapshotDateBetweenOrderBySnapshotDate(b.id,s,e).stream().map(x->new Point(x.snapshotDate.toString(),x.rating)).toList();} public List<Point> scanPoints(Business b,LocalDate s,LocalDate e){QrCode q=codes.findFirstByBusinessIdAndActiveTrue(b.id).orElse(null);if(q==null)return List.of();Map<LocalDate,Long> grouped=scans.findByQrCodeIdAndScannedAtBetween(q.id,s.atStartOfDay(ZoneOffset.UTC).toInstant(),e.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant()).stream().collect(Collectors.groupingBy(x->x.scannedAt.atZone(ZoneOffset.UTC).toLocalDate(),Collectors.counting()));return s.datesUntil(e.plusDays(1)).map(d->new Point(d.toString(),grouped.getOrDefault(d,0L))).toList();} private ReviewSnapshot at(UUID b,LocalDate day){return snapshots.findFirstByBusinessIdAndSnapshotDateLessThanEqualOrderBySnapshotDateDesc(b,day).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.CONFLICT,"No review history is available yet."));}private long scans(Business b,LocalDate s,LocalDate e){return codes.findFirstByBusinessIdAndActiveTrue(b.id).map(q->scans.countByQrCodeIdAndScannedAtBetween(q.id,s.atStartOfDay(ZoneOffset.UTC).toInstant(),e.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant())).orElse(0L);}private double round(double n){return Math.round(n*10.0)/10.0;}}
